  ('de32d197-9ae6-561b-a372-9e73829dff82'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un pouvoir reçu, pas conquis","competence":"analyser-document","situation":"Élodie doit répondre à une question d’élève : « Hitler a-t-il gagné les élections pour devenir chancelier ? » Elle compare des résultats électoraux et un récit de la journée du 30 janvier 1933.","documents":[{"id":"graph","type":"graphique","forme":"barres","titre":"Les voix du NSDAP aux élections au Reichstag","source":"Résultats arrondis au dixième.","categories":["Mai 1928","Sept. 1930","Juil. 1932","Nov. 1932"],"series":[{"nom":"Voix du NSDAP","valeurs":[2.6,18.3,37.3,33.1],"teinte":"violet"}],"axeY":{"titre":"Part des voix","unite":"en %","min":0,"max":40,"pas":10},"axeX":{"titre":"Élection"},"valeurs":true},{"id":"texte","type":"texte","genre":"source","titre":"Le 30 janvier 1933","auteur":"Texte écrit pour l’exercice, d’après le cours","blocs":["Le 30 janvier 1933, le président Hindenburg nomme Adolf Hitler chancelier. Le NSDAP n’a pas la majorité au Reichstag : Hitler dirige un gouvernement de coalition, où les nazis ne tiennent que trois postes sur onze.","Quelques semaines plus tard, l’incendie du Reichstag sert de prétexte à la suspension des libertés, puis les pleins pouvoirs sont votés."]}],"questions":[{"enonce":"Touche la barre de l’élection où le NSDAP réalise son meilleur score.","aide":"Cherche la barre la plus haute.","type":"zone","document":"graph","multiple":false},{"enonce":"De combien de points le score du NSDAP recule-t-il entre juillet et novembre 1932 ?","aide":"Soustrais les deux valeurs écrites au bout des barres.","type":"nombre","unite":"points"},{"enonce":"Touche le mot du texte qui donne le nom de celui qui nomme Hitler chancelier.","aide":"Lis la première phrase.","type":"zone","document":"texte","multiple":false},{"enonce":"Comment Hitler accède-t-il au pouvoir ?","aide":"Regarde le meilleur score du NSDAP, puis qui signe la nomination.","type":"choix","options":[{"id":"a","texte":"Par une élection où le NSDAP obtient la majorité absolue des voix"},{"id":"b","texte":"Par un référendum où les Allemands le choisissent comme chancelier"},{"id":"c","texte":"Par un coup d’État militaire réussi contre la République de Weimar"},{"id":"d","texte":"Par une nomination légale, puis en détruisant les règles de l’intérieur"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"C’est **juillet 1932**, avec 37,3 % des voix : le meilleur score libre du parti."},{"cle":{"type":"nombre","valeur":4.2,"tolerance":0.05},"affichage":"4,2 points","explication":"37,3 − 33,1 = **4,2 points** : le parti recule, et n’a jamais eu la majorité absolue."},{"cle":{"type":"zone","ids":["m6"]},"explication":"C’est **Hindenburg**, le président de la République : Hitler est nommé, il n’a pas pris le pouvoir par la force."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le NSDAP n’a jamais dépassé **37,3 %** et c’est le président qui nomme Hitler : le pouvoir est **reçu légalement**, puis les règles sont détruites de l’intérieur."}]$ex$::jsonb),
  ('de32d197-9ae6-561b-a372-9e73829dff82'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une journée en Allemagne nazie","competence":"analyser-document","situation":"Une lectrice imagine le quotidien de Karl, treize ans, à Berlin en 1937. En suivant son récit et la carte de l’Europe, elle relie la vie quotidienne aux ambitions du régime.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Berlin, 1937","auteur":"Récit écrit pour l’exercice","blocs":["Chaque samedi, Karl enfile l’uniforme des Jeunesses hitlériennes. À la radio, la voix de Goebbels répète les mêmes slogans. Son voisin, M. Weiss, a dû fermer son magasin depuis les lois de Nuremberg.","Un soir, des hommes de la Gestapo emmènent un ami de son père. On dit qu’il est parti pour Dachau, l’un des premiers camps, ouvert dès 1933."]},{"id":"carte","type":"carte","titre":"L’Europe des ambitions nazies","source":"Carte schématique.","fond":"europe","cadrage":[0,42,32,60],"regionsCliquables":true,"regions":[{"code":"DEU","teinte":"ambre","motif":"clair","etiquette":"Allemagne"}],"legende":[{"teinte":"ambre","motif":"clair","texte":"Allemagne nazie en 1933"}]}],"questions":[{"enonce":"Touche l’Autriche, annexée par l’Allemagne en mars 1938.","aide":"Elle est au sud de l’Allemagne, dans les Alpes.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la Pologne, envahie le 1er septembre 1939.","aide":"Elle est à l’est de l’Allemagne.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche le mot du récit qui désigne la police politique du régime.","aide":"C’est un acronyme allemand, cité à la fin du récit.","type":"zone","document":"recit","multiple":false},{"enonce":"Range chaque mesure du régime selon l’instrument qu’elle illustre.","aide":"Demande-toi si la mesure fait peur, fait croire ou fait entrer dans les rangs.","type":"categories","categories":[{"id":"c0","texte":"Terreur"},{"id":"c1","texte":"Propagande"},{"id":"c2","texte":"Embrigadement"}],"items":[{"id":"i0","texte":"Les Jeunesses hitlériennes encadrent les adolescents"},{"id":"i1","texte":"Les Jeux de Berlin servent de vitrine au régime"},{"id":"i2","texte":"La Gestapo arrête les opposants"},{"id":"i3","texte":"Goebbels contrôle la radio et la presse"},{"id":"i4","texte":"Le camp de Dachau ouvre en 1933"}]},{"enonce":"Complète ce bilan.","aide":"Un seul parti est autorisé, et l’idéologie hiérarchise l’humanité.","type":"trous","segments":["Le régime nazi repose sur un parti ",0,", une police politique et une idéologie fondée sur la ",1,"."],"banque":["classe","nation","race","unique"]}]}$ex$::jsonb,
