  ('2f1fe78b-2b4c-5105-b629-4f3e4e8a6d9a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Octobre 1922 : le roi appelle Mussolini","competence":"analyser-document","situation":"Zoé prépare un exposé sur les limites du fascisme italien : elle lit un récit de la marche sur Rome, puis un tableau qui montre ce que le régime contrôle et ce qui lui échappe.","documents":[{"id":"texte","type":"texte","genre":"source","titre":"La marche sur Rome","auteur":"Texte écrit pour l’exercice, d’après le cours","blocs":["Fin octobre 1922, des milliers de chemises noires convergent vers Rome. Le gouvernement demande l’état de siège ; le roi Victor-Emmanuel III refuse de le signer.","Il appelle alors Mussolini à Rome et le charge de former le gouvernement. Mussolini n’a pas pris le pouvoir par la force : il l’a reçu du roi."]},{"id":"tab","type":"tableau","titre":"Ce que contrôle le régime et ce qui lui échappe","source":"D’après le cours.","colonnes":["Domaine","Ce que fait le régime","Ce qui lui échappe"],"enteteLignes":true,"lignes":[["Jeunesse","Les Balilla","Aucun contre-pouvoir"],["Loisirs","Le Dopolavoro","Aucun contre-pouvoir"],["Pouvoir d’État","Le Duce et le parti unique","La monarchie, qui reste en place"],["Religion","Les accords du Latran (1929)","L’Église, qui garde son autonomie"]]}],"questions":[{"enonce":"Touche le mot du texte qui donne le nom du roi qui refuse l’état de siège.","aide":"Lis la dernière phrase du premier paragraphe.","type":"zone","document":"texte","multiple":false},{"enonce":"Touche les deux cases qui montrent ce qui échappe au contrôle du Duce.","aide":"Regarde la colonne « Ce qui lui échappe » : deux lignes sont différentes des autres.","type":"zone","document":"tab","multiple":true},{"enonce":"Combien d’années séparent la marche sur Rome de la signature des accords du Latran ?","aide":"Une date est dans le texte, l’autre dans le tableau.","type":"nombre","unite":"ans"},{"enonce":"Que montre le document 1 sur l’arrivée de Mussolini au pouvoir ?","aide":"Relis qui refuse, puis qui appelle Mussolini.","type":"choix","options":[{"id":"a","texte":"Les électeurs lui donnent la majorité absolue lors d’un scrutin libre"},{"id":"b","texte":"L’armée royale écrase les chemises noires aux portes de la capitale"},{"id":"c","texte":"Le roi lui confie le gouvernement au lieu de défendre l’État contre lui"},{"id":"d","texte":"Le pape l’appelle au pouvoir après un accord signé avec le Vatican"}],"multiple":false}]}$ex$::jsonb,
