   $ex${"titre":"La terreur et l’État soviétique","competence":"raisonner","situation":"Une lycéenne prépare une composition sur la terreur stalinienne : elle lit le récit d’un procès de Moscou, repère les lieux de déportation sur une carte, puis classe les instruments du pouvoir.","documents":[{"id":"texte","type":"texte","genre":"article","titre":"Un procès de Moscou","auteur":"Texte écrit pour l’exercice, d’après le cours","blocs":["Août 1936, Moscou. Zinoviev et Kamenev, anciens compagnons de Lénine, comparaissent devant un tribunal. Ils reconnaissent publiquement des crimes inventés et sont fusillés. Deux autres procès suivent, en 1937 et 1938.","Ces aveux arrachés par le NKVD servent à montrer que le régime est entouré d’ennemis. Pendant ce temps, des centaines de milliers de personnes sont exécutées et des millions déportées au Goulag."]},{"id":"carte","type":"carte","titre":"Moscou et trois lieux de déportation","source":"Carte schématique.","fond":"monde","cadrage":[25,40,170,75],"lieux":[{"id":"z1","lieu":"moscou","symbole":"point","nom":"Moscou"},{"id":"z2","lon":64.03,"lat":67.5,"symbole":"point","nom":"Vorkouta"},{"id":"z3","lon":88.2,"lat":69.35,"symbole":"point","nom":"Norilsk"},{"id":"z4","lon":150.8,"lat":59.56,"symbole":"point","nom":"Magadan"}]}],"questions":[{"enonce":"Touche le mot du texte qui désigne ce que les accusés reconnaissent publiquement.","aide":"Le mot est au début du deuxième paragraphe.","type":"zone","document":"texte","multiple":false},{"enonce":"Touche Magadan, le lieu de déportation le plus éloigné de Moscou.","aide":"Cherche le point tout à l’est, près du Pacifique.","type":"zone","document":"carte","multiple":false},{"enonce":"Range chaque élément du système stalinien dans la bonne catégorie.","aide":"Trois catégories : faire peur, transformer l’économie, façonner les esprits.","type":"categories","categories":[{"id":"c0","texte":"Terreur"},{"id":"c1","texte":"Transformation de l’économie"},{"id":"c2","texte":"Encadrement des esprits"}],"items":[{"id":"i0","texte":"Le réalisme socialiste imposé aux artistes"},{"id":"i1","texte":"Les grandes purges de 1936-1938"},{"id":"i2","texte":"Les plans quinquennaux"},{"id":"i3","texte":"L’industrialisation à marche forcée"},{"id":"i4","texte":"Les Komsomols pour la jeunesse"},{"id":"i5","texte":"Le NKVD"},{"id":"i6","texte":"Le Goulag"},{"id":"i7","texte":"Le culte de la personnalité de Staline"}]},{"enonce":"Associe chaque mot du vocabulaire soviétique à sa définition.","aide":"Reprends le texte et le cours : chaque mot y est lié à un acteur ou à une institution.","type":"association","gauche":[{"id":"g0","texte":"NKVD"},{"id":"g1","texte":"Kolkhoze"},{"id":"g2","texte":"Goulag"},{"id":"g3","texte":"Koulak"}],"droite":[{"id":"d0","texte":"Système de camps de travail"},{"id":"d1","texte":"Police politique"},{"id":"d2","texte":"Paysan présenté comme aisé"},{"id":"d3","texte":"Ferme collective"}]},{"enonce":"Pourquoi qualifie-t-on ce régime de totalitaire et non simplement d’autoritaire ?","aide":"Un régime autoritaire se contente d’obéissance ; que demande celui-ci ?","type":"choix","options":[{"id":"a","texte":"Il se contente de maintenir l’ordre par une armée très présente"},{"id":"b","texte":"Il exige l’adhésion de tous et prétend transformer la société"},{"id":"c","texte":"Il tolère les opinions privées tant qu’elles restent silencieuses"},{"id":"d","texte":"Il partage le pouvoir avec une monarchie et une Église puissantes"}],"multiple":false}]}$ex$::jsonb,
