   $ex${"titre":"Obéir ou adhérer ?","competence":"analyser-texte","situation":"Un élève demande à son professeur pourquoi on ne dit pas simplement « dictature ». Elle répond avec une notice sur le mot « totalitarisme » et un tableau qui oppose deux types de régimes.","documents":[{"id":"texte","type":"texte","genre":"article","titre":"Le mot « totalitarisme »","auteur":"Notice écrite pour l’exercice, d’après le cours","blocs":["Le mot « totalitarisme » est forgé dans les années 1920-1930. La philosophe Hannah Arendt le popularise en 1951 dans *Les Origines du totalitarisme*. Un régime autoritaire se contente d’obtenir l’obéissance ; un régime totalitaire exige l’adhésion de chacun.","Le concept a pourtant été critiqué : il rapproche des régimes très différents et il a beaucoup servi d’argument politique pendant la guerre froide."]},{"id":"tab","type":"tableau","titre":"Autoritaire ou totalitaire ?","source":"D’après le cours.","colonnes":["","Régime autoritaire","Régime totalitaire"],"enteteLignes":true,"lignes":[["Ce que le pouvoir exige","L’obéissance","L’adhésion"],["Vie privée","Tolérée si l’on se tait","Contrôlée et mobilisée"],["Jeunesse","Peu encadrée","Embrigadée dans des organisations du parti"]]}],"questions":[{"enonce":"Touche la case qui décrit la jeunesse sous un régime totalitaire.","aide":"Cherche la ligne « Jeunesse », colonne « Régime totalitaire ».","type":"zone","document":"tab","multiple":false},{"enonce":"Range chaque trait dans le type de régime qui lui correspond.","aide":"Un seul type de régime se contente du silence.","type":"categories","categories":[{"id":"c0","texte":"Autoritaire"},{"id":"c1","texte":"Totalitaire"}],"items":[{"id":"i0","texte":"La jeunesse est embrigadée dans des organisations du parti"},{"id":"i1","texte":"Les opinions privées sont tolérées tant qu’elles restent silencieuses"},{"id":"i2","texte":"Le régime veut façonner un homme nouveau"},{"id":"i3","texte":"Le citoyen doit adhérer à l’idéologie officielle"},{"id":"i4","texte":"Le pouvoir se contente que l’on obéisse"}]},{"enonce":"Touche le mot du texte qui résume ce qu’un régime totalitaire exige de chacun.","aide":"Cherche ce qu’il exige, contrairement à l’obéissance.","type":"zone","document":"texte","multiple":false},{"enonce":"Quelle critique le texte adresse-t-il au concept de totalitarisme ?","aide":"Relis le deuxième paragraphe.","type":"choix","options":[{"id":"a","texte":"Il confond les régimes autoritaires avec les démocraties libérales"},{"id":"b","texte":"Il rapproche des régimes différents et a servi d’arme politique"},{"id":"c","texte":"Il sépare trop nettement des régimes qui se ressemblent vraiment"},{"id":"d","texte":"Il ne s’applique qu’aux régimes qui ont existé après 1945"}],"multiple":false}]}$ex$::jsonb,
